# Новые события по всей жизни: content/events/extra.json. У каждого — 2–3 формулировки.
# Детство поколения 2013–2020 и будущих лет, новые истории юности, взрослой жизни и особенно старости.
import json, os
ROOT = os.path.join(os.path.dirname(__file__), '..')
E = []
def ev(id, age, texts, cond=None, fx=None, time='any', **kw):
    e = {'id': id, 'age': age, 'time': time, 'text': texts[0], 'texts': texts}
    if cond: e['if'] = cond
    if fx: e['fx'] = fx
    e.update(kw); E.append(e)
Y = lambda a, b, **k: {'years': [a, b], **k}
RU = ['abroad']

